instances = env['shopify.instance'].search([('state', '=', 'connected')])
for inst in instances:
    env['shopify.queue'].enqueue_historical_import(inst, 'collections', {'chunked': True})
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'Sync Collections',
        'message': ('Collection sync started in the background for %d store(s). '
                    'Track progress in Monitoring → Sync Queue.') % len(instances)
                   if instances else 'No connected stores.',
        'type': 'success' if instances else 'warning',
    },
}

